#include <cstddef>
#include <cstdint>
extern "C" std::int64_t kahn(const std::int64_t*v,std::size_t n){if(!v||n<2||n>258)return -2;auto nv=v[0],ne=v[1];if(nv<0||nv>32||ne<0||ne>128||n!=2+2*static_cast<std::size_t>(ne))return -2;bool adj[32][32]={};int indegree[32]={};int q[32];for(std::size_t i=0;i<static_cast<std::size_t>(ne);i++){auto a=v[2+2*i],b=v[3+2*i];if(a<0||a>=nv||b<0||b>=nv)return -2;if(!adj[a][b]){adj[a][b]=true;indegree[b]++;}}int head=0,tail=0;for(int i=0;i<nv;i++)if(indegree[i]==0)q[tail++]=i;while(head<tail){int x=q[head++];for(int y=0;y<nv;y++)if(adj[x][y]){indegree[y]--;if(indegree[y]==0)q[tail++]=y;}}return tail==nv?nv:-1;}
